 ('SubtitleFiles', 'SpeechAccuracy', 'SilenceHallucination', "model.transcribe('silence.wav')",
  'Ten seconds of digital silence were transcribed by tiny as  You in 1 segment, and ten seconds of seeded noise as  in 0 segments: Whisper can write words where nobody spoke, so a transcript is not proof of speech.',
  (X(_PRE + '\nimport random\ndef mk(path, f):\n    w = wave.open(path, \'wb\'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(16000); w.writeframes(array.array(\'h\', [f() for _ in range(160000)]).tobytes()); w.close()\nrandom.seed(1); mk(\'s.wav\', lambda: 0); mk(\'n.wav\', lambda: random.randint(-3000, 3000))\ncode = "import whisper\\nm = whisper.load_model(\'tiny\')\\nfor f in (\'s.wav\', \'n.wav\'):\\n    r = m.transcribe(f, language=\'en\'); print(repr(r[\'text\']), len(r[\'segments\']))"\na, b = py(code)[1].split(\'\\n\')\nout = (eval(a.rsplit(\' \', 1)[0]), int(a.rsplit(\' \', 1)[1]), eval(b.rsplit(\' \', 1)[0]), int(b.rsplit(\' \', 1)[1]))\n'), "(' You', 1, '', 0)")),
